// Generated by `just generate` from `src/plugins/claudetto/slices/reads/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handler of the `reads` slice: `tool.call` with three gates.
//
// 1. A call that the user rejected in the dialog is denied when it comes again with the same input, in the same session.
// 2. A `Read` is denied when earlier reads of an unchanged file cover its lines and their results are still in the context.
// 3. A `Write` or an `Edit` of a file is denied after a rejected write of that file, until Claude reads the file.
//
// The hook wraps the permission check and its dialog, so the result of `next` shows a rejection (decision D61).
// A hook that calls `next` first has no catch-all (D49).
// A plugin verdict only makes a call stricter, so each gate only denies (D53).
//
// `claude plugin validate` follows `$` only into a function of one file.
// For this reason, each function that touches `$` is here, and the rules are in `domain/`.
//
// The state is in memory, by session id.
// A restart of the session starts with no record, so the gates then allow.

import type { EngineInterface } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import {
  coveringSpan,
  type FileRecord,
  idsInContext,
  type Span,
  spanKey,
  spanOf,
  spanText,
  withRead,
} from "../domain/ranges.ts";
import { callKey, inputOf, isRejected, remember } from "../domain/rejected.ts";
import { MAX_REMEMBERED } from "../limits.ts";
import { DENY_READ, DENY_REJECTED, DENY_REREAD } from "../prompts.ts";

/** The keys of the calls that the user rejected, by session. */
const rejected = new Map<string, Set<string>>();

/** The files that a rejected write left to read again, by session. */
const stale = new Map<string, Set<string>>();

/** The records of reads, by session and then by agent (`""` is the main loop) and then by path. */
const reads = new Map<string, Map<string, Map<string, FileRecord>>>();

const setOf = <T>(map: Map<string, Set<T>>, session: string): Set<T> => {
  const found = map.get(session) ?? new Set<T>();
  map.set(session, found);
  return found;
};

const recordsOf = (session: string, agent: string): Map<string, FileRecord> => {
  const agents =
    reads.get(session) ?? new Map<string, Map<string, FileRecord>>();
  reads.set(session, agents);
  const found = agents.get(agent) ?? new Map<string, FileRecord>();
  agents.set(agent, found);
  return found;
};

/** The stats of a file, or undefined when the file is not there. A stat error leaves the read to report it. */
const statOf = async (
  $: EngineInterface,
  path: string,
): Promise<{ mtimeMs: number; size: number } | undefined> => {
  const stat = await $.fs.stat(path).catch(() => undefined);
  return stat?.kind === "file"
    ? { mtimeMs: stat.mtimeMs, size: stat.size }
    : undefined;
};

/** The earlier span that holds `span` and whose results are in the context, or undefined. */
const coveredNow = async (
  $: EngineInterface,
  record: FileRecord,
  span: Span,
  agentId: string | undefined,
): Promise<Span | undefined> => {
  if (coveringSpan(record.seen, span) === undefined) return undefined;
  const found = await $.session.messages({
    as: "api",
    ...(agentId === undefined ? {} : { agentId }),
  } as never);
  if (!Array.isArray(found)) return undefined;
  const live = idsInContext(found, new Set(record.seen.map((s) => s.id)));
  return coveringSpan(
    record.seen.filter((s) => live.has(s.id)),
    span,
  );
};

/** True when a tool writes a file by the path in `file_path`. */
const writes = (tool: string): boolean => tool === "Write" || tool === "Edit";

// The session id comes from `$` and not from the event, so a call that no gate needs does not ask for it.
// A `Read` always needs it.
// A `Write` or an `Edit` needs it only after some rejected write, and another tool only after some rejection.
const needsSession = (tool: string): boolean =>
  tool === "Read" || (writes(tool) ? stale.size > 0 : rejected.size > 0);

export const onToolCall: Handler<"tool.call"> = async ($, e, next) => {
  const early = needsSession(e.tool) ? await $.session.id() : undefined;
  const key = callKey(e.tool, inputOf(e));
  if (early !== undefined && rejected.get(early)?.has(key))
    return { deny: DENY_REJECTED({ tool: e.tool }) };

  const path =
    "file_path" in e && typeof e.file_path === "string"
      ? e.file_path
      : undefined;
  if (early !== undefined && writes(e.tool) && path !== undefined) {
    if (stale.get(early)?.has(path))
      return { deny: DENY_REREAD({ tool: e.tool, path }) };
  }

  const gate =
    early !== undefined &&
    e.tool === "Read" &&
    path !== undefined &&
    !("pages" in e && e.pages)
      ? {
          path,
          records: recordsOf(early, e.agentId ?? ""),
          span: spanOf(e.offset, e.limit),
        }
      : undefined;
  const stat = gate ? await statOf($, gate.path) : undefined;
  if (gate && stat) {
    const record = gate.records.get(gate.path);
    if (
      record &&
      record.mtimeMs === stat.mtimeMs &&
      record.size === stat.size
    ) {
      const covering = await coveredNow($, record, gate.span, e.agentId);
      const mark = spanKey(gate.span);
      if (covering && record.denied.includes(mark))
        gate.records.set(gate.path, {
          ...record,
          denied: record.denied.filter((d) => d !== mark),
        });
      else if (covering) {
        gate.records.set(gate.path, {
          ...record,
          denied: [...record.denied, mark],
        });
        return {
          deny: DENY_READ({ path: gate.path, range: spanText(covering) }),
        };
      }
    }
  }

  const out = await next(e);
  if (out.deny !== undefined) return out;
  if (isRejected(out)) {
    const session = early ?? (await $.session.id());
    remember(setOf(rejected, session), key, MAX_REMEMBERED);
    if (writes(e.tool) && path !== undefined) {
      remember(setOf(stale, session), path, MAX_REMEMBERED);
      for (const agent of reads.get(session)?.values() ?? [])
        agent.delete(path);
    }
    return out;
  }
  if (gate && early !== undefined) stale.get(early)?.delete(gate.path);
  if (gate && stat && !out.isError) {
    gate.records.set(
      gate.path,
      withRead(gate.records.get(gate.path), stat, {
        id: e.tool_use_id,
        span: gate.span,
      }),
    );
    for (const old of gate.records.keys()) {
      if (gate.records.size <= MAX_REMEMBERED) break;
      gate.records.delete(old);
    }
  }
  return out;
};
